begin;
create temp table mention_fixture(label text,id uuid);insert into mention_fixture values('self',gen_random_uuid()),('father',gen_random_uuid()),('brother',gen_random_uuid()),('other',gen_random_uuid()),('pending',gen_random_uuid());grant select on mention_fixture to authenticated;
insert into public.allowed_families(name) values('اختبارمنشن');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select id,id::text||'@example.invalid',now(),jsonb_build_object('full_name',case label when 'self' then 'منشن علي حسن اختبارمنشن' when 'father' then 'أحمد زيد علي اختبارمنشن' when 'brother' then 'أحمد حسن علي اختبارمنشن' when 'other' then 'أحمد ابراهيم علي اختبارمنشن' else 'أحمد معلق علي اختبارمنشن' end,'gender','male','phone',case label when 'self' then '+966500008811' when 'father' then '+966500008812' when 'brother' then '+966500008813' when 'other' then '+966500008814' else '+966500008815' end) from mention_fixture;
update public.profiles set status=case when id=(select id from mention_fixture where label='pending') then 'pending' else 'active' end where id in(select id from mention_fixture);
update public.profiles p set display_name=u.raw_user_meta_data->>'full_name' from auth.users u where p.id=u.id and p.id in(select id from mention_fixture);
insert into family_private.personal_kinship(owner_id,member_id,relation) select (select id from mention_fixture where label='self'),id,label from mention_fixture where label in('father','brother');
select set_config('request.jwt.claim.sub',(select id::text from mention_fixture where label='self'),true);
set local role authenticated;
do $$declare result jsonb;begin
 result=public.mention_search('');if result->0->>'id'<>(select id::text from mention_fixture where label='father') or result->1->>'id'<>(select id::text from mention_fixture where label='brother') then raise exception 'Kinship order failed';end if;
 result=public.mention_search('أ');if not exists(select 1 from jsonb_array_elements(result) x where x->>'id'=(select id::text from mention_fixture where label='father')) then raise exception 'First character failed';end if;
 result=public.mention_search('أحمد ز');if jsonb_array_length(result)<>1 or result->0->>'id'<>(select id::text from mention_fixture where label='father') then raise exception 'Progressive prefix failed';end if;
 if result::text like '%email%' or result::text like '%phone%' then raise exception 'Private details leaked';end if;
 result=public.mention_search('أحمد معلق');if result<>'[]'::jsonb then raise exception 'Pending profile leaked';end if;
end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from mention_fixture where label='other'),true);
set local role authenticated;
do $$declare result jsonb;begin result=public.mention_search('أحمد ز');if result->0->>'relation_label' is not null or (result->0->>'proximity')::int<>9 then raise exception 'Another user tree leaked';end if;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from mention_fixture where label='pending'),true);
set local role authenticated;
do $$begin begin perform public.mention_search('');raise exception 'PENDING_ACCEPTED';exception when raise_exception then if sqlerrm='PENDING_ACCEPTED' then raise;end if;end;end$$;
reset role;
set local role anon;
do $$begin begin perform public.mention_search('');raise exception 'ANON_ACCEPTED';exception when insufficient_privilege then null;end;end$$;
reset role;
select 'PASS: kinship order, first letter and progressive Arabic prefix, private details/tree/pending/anonymous isolation' as result;
rollback;
